/** Pure reading and backup logic, independent of browser and storage. */
export const MAX_TEXT = 1_000_000;
export const MAX_DOCUMENTS = 500;
export function checkLibrarySize(documents){if(new TextEncoder().encode(JSON.stringify(documents)).byteLength>20_000_000)throw Error('Your library has reached 20 MB. Export a backup, then remove older readings before adding more.');}
export const DEFAULT_SETTINGS = Object.freeze({mode:'flow',speed:250,size:22,strength:50,pauses:true,dark:false});
export const wordsOf = text => text.match(/\S+/gu) || [];
const segmenter = typeof Intl.Segmenter === 'function' ? new Intl.Segmenter(undefined,{granularity:'grapheme'}) : null;
export const graphemes = text => segmenter ? Array.from(segmenter.segment(text),s=>s.segment) : Array.from(text);
export function splitWord(word){const c=graphemes(word);const p=Math.max(0,Math.ceil(c.length*.35)-1);return [c.slice(0,p).join(''),c[p]||'',c.slice(p+1).join('')];}
export function duration(word,speed,pauses){let time=60000/speed;if(pauses){if(/[.!?…]["'”’\)\]]*$/.test(word))time*=2.2;else if(/[,;:—]["'”’\)\]]*$/.test(word))time*=1.5;}return time;}
export function remainingTimes(words,speed,pauses){const times=new Array(words.length+1).fill(0);for(let i=words.length-1;i>=0;i--)times[i]=times[i+1]+duration(words[i],speed,pauses);return times;}
export function normalizeSettings(s={}){const value=(key,min,max)=>Number.isFinite(s[key])?Math.max(min,Math.min(max,s[key])):DEFAULT_SETTINGS[key];return {mode:['flow','bold','classic'].includes(s.mode)?s.mode:'flow',speed:value('speed',100,800),size:value('size',16,34),strength:value('strength',20,70),pauses:typeof s.pauses==='boolean'?s.pauses:true,dark:typeof s.dark==='boolean'?s.dark:false};}
export function validateBackup(data){if(!data||data.format!=='flow-reader'||data.version!==1||!Array.isArray(data.documents))throw Error('Choose a Flow backup (.json), version 1.');if(data.documents.length>MAX_DOCUMENTS)throw Error('This backup contains too many readings.');let total=0;const ids=new Set();const documents=data.documents.map(d=>{if(!d||typeof d.id!=='string'||!d.id||d.id.length>150||ids.has(d.id)||typeof d.title!=='string'||d.title.length>150||typeof d.text!=='string'||d.text.length>MAX_TEXT)throw Error('This backup contains an invalid reading.');ids.add(d.id);total+=d.text.length;if(total>20_000_000)throw Error('This backup is too large.');const length=wordsOf(d.text).length;const position=Number.isInteger(d.position)?Math.max(0,Math.min(d.position,Math.max(0,length-1))):0;if(!Array.isArray(d.bookmarks)||d.bookmarks.length>1000||d.bookmarks.some(b=>!Number.isInteger(b)||b<0||b>=length))throw Error('This backup contains an invalid bookmark.');return {id:d.id,title:d.title,text:d.text,position,bookmarks:[...new Set(d.bookmarks)].sort((a,b)=>a-b),updatedAt:typeof d.updatedAt==='number'&&Number.isFinite(d.updatedAt)?d.updatedAt:Date.now()};});checkLibrarySize(documents);return documents;}
export function mergeDocuments(existing,incoming,makeId){const result=existing.map(d=>({...d,bookmarks:[...d.bookmarks]}));let added=0;for(const doc of incoming){const same=result.find(d=>d.text===doc.text&&d.title===doc.title);if(same){same.bookmarks=[...new Set([...same.bookmarks,...doc.bookmarks])].sort((a,b)=>a-b);continue;}const match=result.find(d=>d.id===doc.id);result.push({...doc,id:match?makeId():doc.id,bookmarks:[...doc.bookmarks]});added++;}if(result.length>MAX_DOCUMENTS)throw Error(`A library can contain up to ${MAX_DOCUMENTS} readings. Export a backup before removing old readings.`);checkLibrarySize(result);return {documents:result,added};}
export function decodeLibrary(value){if(!value||value.version!==1)throw Error('This library version is not supported.');return {version:1,documents:validateBackup({format:'flow-reader',version:1,documents:value.documents}),activeId:typeof value.activeId==='string'?value.activeId:null,settings:normalizeSettings(value.settings)};}
